mapper.select:
SELECT c.COMPANY_IDX AS company_idx, u.USER_IDX AS users_idx, u.USER_NAME AS user_name, u.LOGIN_ID AS login_id, u.STATUS AS status,
c.COMPANY_NUM AS company_num, c.PHONE AS phone, c.ADDRESS AS address, c.EMAIL AS email,
NVL(ce.CERT_STATUS, '미등록') AS cert_status FROM USERS u JOIN COMPANY c ON c.USER_IDX = u.USER_IDX LEFT JOIN CERT ce ON ce.USER_IDX = u.USER_IDX AND ce.CERT_TYPE = '사업증' WHERE u.USER_IDX = #{value}
